import ast
for path in ['rosterkit/contacts.py', 'tests/test_contacts.py']:
    text = open(path).read()
    tree = ast.parse(text)
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            size = node.end_lineno - node.lineno + 1
            if size > 8:
                print(path, node.name, 'lines', size)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store) and len(node.id) < 4:
            print(path, 'short name', node.id, node.lineno)
        if isinstance(node, ast.arg) and len(node.arg) < 4:
            print(path, 'short arg', node.arg)
    print(path, 'double blank:', '\n\n\n' in text)
"; grep -n "" rosterkit/contacts.py | head -0

