import ast
for path in ['rosterkit/contacts.py', 'tests/test_contacts.py']:
    text = open(path).read()
    lines = text.split('\n')
    blanks = [n for n in range(len(lines) - 1) if lines[n] == '' and lines[n + 1] == '']
    print(path, 'double blank pairs:', blanks)
    tree = ast.parse(text)
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
            size = node.end_lineno - node.lineno + 1
            if isinstance(node, ast.FunctionDef) and size > 8:
                print(path, node.name, 'lines', size)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store) and len(node.id) < 4:
            print(path, 'short name', node.id, node.lineno)
        if isinstance(node, ast.arg) and len(node.arg) < 4:
            print(path, 'short arg', node.arg)
        if isinstance(node, ast.For) and len(node.target.id) < 4:
            print(path, 'short loop var', node.target.id)
    print(path, 'checked')
"; echo done

